"""Class to represent a beam object used in setting up a Deliver Quick Beam in Integrity service mode"""

class Beam(object):
    """
    Responsibility: Represent a well defined concept from the problem domain.
    Knows:  Specific details, attributes, behaviours of the concept it represents.
    Does:  Very limited activity on the data that it contains and understands
    Collaborators: Other domain objects

    Comments: Should remain blissfully unaware that it is used by other objects.
    Currently a very basic Beam representation for running quick beam.

    Args:
        object: Dictionary of beam data
    """


    def __init__(self,data_row):
        self.header_to_func_mapping = {
        "Beam.energy": self.set_beam_energy,
        "Beam.mu1": self.set_beam_mu1,
        "Beam.mu2": self.set_beam_mu2,
        "Beam.name": self.set_name,
        "Beam.maxdoserate": self.set_max_dose_rate
        }
        print(data_row)
        self.raw_data = data_row
        self.set_data()

    def __str__(self):
        debug_data = (self.raw_data["Beam.name"],
                      self.raw_data["Beam.energy"],
                      self.raw_data["Beam.mu1"],
                      self.raw_data["Beam.mu2"],
                      self.raw_data["Beam.maxdoserate"])
        return ("(" + ", ".join(debug_data) + ")")


    def set_data(self):
        """
        Populates instance variables with data from data row (usually from csv,
        could be from a test config object though) using mapped functions paired
        with column header values.

        For each header (column) get the data from the data row and call the
        function associated with that header with the data value as parameter.
        key = column header e.g. "maxdoserate"
        value = function to call e.g. self.set_max_dose_rate
        """

        for key, value in self.header_to_func_mapping.items():
            data = self.raw_data[key]
            #call function with data argument
            value(data)

    def set_name(self, value):
        self.name = value

    def get_name(self):
        return self.name

    def set_beam_energy(self, value):
        self.beam_energy = value

    def set_beam_mu1(self, value):
        self.beam_mu1 = value

    def set_beam_mu2(self, value):
        self.beam_mu2 = value

    def set_max_dose_rate(self, value):
        self.max_dose_rate = value

    def get_beam_energy(self):
        return self.beam_energy

    def get_beam_mu1(self):
        return self.beam_mu1

    def get_beam_mu2(self):
        return self.beam_mu2

    def get_max_dose_rate(self):
        return self.max_dose_rate